CREATE TABLE IF NOT EXISTS "credential_import_jobs" ("id" TEXT NOT NULL PRIMARY KEY, "status" TEXT NOT NULL DEFAULT 'previewed', "target" TEXT, "site_id" INTEGER, "operator_id" TEXT NOT NULL, "conflict_policy" TEXT NOT NULL DEFAULT 'skip', "source_format" TEXT NOT NULL, "source_version" TEXT, "source_platform" TEXT, "detection_confidence" TEXT NOT NULL, "detection_is_batch" BOOLEAN NOT NULL DEFAULT false, "detection_warnings" TEXT, "normalization_warnings" TEXT, "batch_fingerprint" TEXT NOT NULL, "request_fingerprint" TEXT NOT NULL, "idempotency_key_hash" TEXT, "candidate_count" INTEGER NOT NULL DEFAULT 0, "duplicate_count" INTEGER NOT NULL DEFAULT 0, "imported_count" INTEGER NOT NULL DEFAULT 0, "updated_count" INTEGER NOT NULL DEFAULT 0, "skipped_count" INTEGER NOT NULL DEFAULT 0, "failed_count" INTEGER NOT NULL DEFAULT 0, "failure_message" TEXT, "started_at" TEXT, "completed_at" TEXT, "created_at" TEXT DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS'), "updated_at" TEXT DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS'), FOREIGN KEY ("site_id") REFERENCES "sites"("id") ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS "credential_import_items" ("id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY, "job_id" TEXT NOT NULL, "source_index" INTEGER NOT NULL, "candidate_fingerprint" TEXT NOT NULL, "source_format" TEXT NOT NULL, "source_version" TEXT, "source_platform" TEXT, "provider" TEXT, "kind" TEXT NOT NULL, "identity_summary" TEXT, "secret_summary" TEXT NOT NULL, "compatible_targets" TEXT NOT NULL, "expires_at" TEXT, "disabled" BOOLEAN NOT NULL DEFAULT false, "candidate_warnings" TEXT, "validation_status" TEXT NOT NULL, "validation_errors" TEXT, "validation_warnings" TEXT, "duplicate_of_index" INTEGER, "status" TEXT NOT NULL DEFAULT 'previewed', "result_message" TEXT, "account_id" INTEGER, "vault_item_ids" TEXT, "completed_at" TEXT, "created_at" TEXT DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS'), "updated_at" TEXT DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS'), FOREIGN KEY ("account_id") REFERENCES "accounts"("id") ON DELETE SET NULL, FOREIGN KEY ("job_id") REFERENCES "credential_import_jobs"("id") ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS "credential_import_provenance" ("id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY, "job_id" TEXT NOT NULL, "item_id" INTEGER NOT NULL, "target_entity_type" TEXT NOT NULL, "target_entity_id" INTEGER NOT NULL, "site_id" INTEGER, "candidate_fingerprint" TEXT NOT NULL, "source_format" TEXT NOT NULL, "source_version" TEXT, "source_platform" TEXT, "provider" TEXT, "operator_id" TEXT NOT NULL, "conflict_policy" TEXT NOT NULL, "import_action" TEXT NOT NULL, "created_at" TEXT DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS'), FOREIGN KEY ("item_id") REFERENCES "credential_import_items"("id") ON DELETE CASCADE, FOREIGN KEY ("job_id") REFERENCES "credential_import_jobs"("id") ON DELETE CASCADE, FOREIGN KEY ("site_id") REFERENCES "sites"("id") ON DELETE SET NULL);
CREATE UNIQUE INDEX "credential_import_items_job_source_index_unique" ON "credential_import_items" ("job_id", "source_index");
CREATE UNIQUE INDEX "credential_import_jobs_idempotency_key_hash_unique" ON "credential_import_jobs" ("idempotency_key_hash");
CREATE UNIQUE INDEX "credential_import_provenance_item_entity_unique" ON "credential_import_provenance" ("item_id", "target_entity_type", "target_entity_id");
CREATE INDEX "credential_import_items_account_id_idx" ON "credential_import_items" ("account_id");
CREATE INDEX "credential_import_items_candidate_fingerprint_idx" ON "credential_import_items" ("candidate_fingerprint");
CREATE INDEX "credential_import_items_job_status_idx" ON "credential_import_items" ("job_id", "status");
CREATE INDEX "credential_import_jobs_request_fingerprint_idx" ON "credential_import_jobs" ("request_fingerprint");
CREATE INDEX "credential_import_jobs_site_created_at_idx" ON "credential_import_jobs" ("site_id", "created_at");
CREATE INDEX "credential_import_jobs_status_created_at_idx" ON "credential_import_jobs" ("status", "created_at");
CREATE INDEX "credential_import_provenance_fingerprint_idx" ON "credential_import_provenance" ("candidate_fingerprint");
CREATE INDEX "credential_import_provenance_site_created_at_idx" ON "credential_import_provenance" ("site_id", "created_at");
CREATE INDEX "credential_import_provenance_target_entity_idx" ON "credential_import_provenance" ("target_entity_type", "target_entity_id");
